INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Authentifizierung dasselbe wie Autorisierung?', 2, '[{"text": "Nein", "correct": true, "because": "Authentifizierung überprüft Identität, Autorisierung Berechtigungen"}, {"text": "Ja", "correct": false, "because": "Verschiedene Konzepte"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Authentifizierung?', 3, '[{"text": "Identität verifizieren", "correct": true, "because": "Sicherstellung der Nutzeridentität"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Anderer Prozess"}, {"text": "Zugriffsrechte erteilen", "correct": false, "because": "Autorisierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden gehören zur Authentifizierung?', 5, '[{"text": "Passwort", "correct": true, "because": "Wissen-basierte Methode"}, {"text": "Biometrie", "correct": true, "because": "Physische Merkmale"}, {"text": "Verschlüsselung", "correct": false, "because": "Sicherheitsmaßnahme, keine Methode"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Zwei-Faktor-Authentifizierung erhöht die Sicherheit. b) Sie ist immer biometrisch.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nicht zwingend biometrisch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Authentifizierung?', 4, '[{"text": "Sicherheitsmethoden", "correct": false, "because": "Kern der Authentifizierung"}, {"text": "Nutzeridentität", "correct": false, "because": "Hauptfokus"}, {"text": "Büroverschönerung", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Authentifizierung Passwörter erfordert?', 2, '[{"text": "Nein", "correct": true, "because": "Andere Methoden möglich"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode ist ein Beispiel für Zwei-Faktor-Authentifizierung?', 3, '[{"text": "Passwort + SMS-Code", "correct": true, "because": "Zwei unabhängige Faktoren"}, {"text": "Nur Passwort", "correct": false, "because": "Ein Faktor"}, {"text": "Nur Fingerabdruck", "correct": false, "because": "Ein Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Authentifizierung?', 5, '[{"text": "Wissen (Passwort)", "correct": true, "because": "Etwas, das man weiß"}, {"text": "Besitz (Token)", "correct": true, "because": "Etwas, das man hat"}, {"text": "Farbauswahl", "correct": false, "because": "Kein Authentifizierungsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Authentifizierung schützt vor unbefugtem Zugriff. b) Sie ist immer zeitaufwendig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zeit variabel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Authentifizierung unwichtig?', 4, '[{"text": "Sicherheitsfaktoren", "correct": false, "because": "Kern der Methode"}, {"text": "Verifizierungsprozess", "correct": false, "because": "Grundlage"}, {"text": "Bürogestaltung", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss Authentifizierung immer online erfolgen?', 2, '[{"text": "Nein", "correct": true, "because": "Auch offline möglich"}, {"text": "Ja", "correct": false, "because": "Flexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet Authentifizierung?', 4, '[{"text": "Erhöhte Sicherheit", "correct": true, "because": "Schützt Daten"}, {"text": "Zugriffskontrolle", "correct": true, "because": "Nur Berechtigte"}, {"text": "Schnellere Prozesse", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Authentifizierung immer Passwörter braucht. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Biometrie, Token möglich"}, {"text": "Ja", "correct": false, "because": "Alternative Methoden"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Authentifizierung?', 3, '[{"text": "Sicherheit", "correct": true, "because": "Schutz vor Zugriff"}, {"text": "Schnelligkeit", "correct": false, "because": "Sekundär"}, {"text": "Design", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Authentifizierung kann biometrisch sein. b) Sie garantiert Autorisierung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Autorisierung separat"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat eine schwache Authentifizierung?', 5, '[{"text": "Sicherheitslücken", "correct": true, "because": "Leichter Zugriff"}, {"text": "Datenverlust", "correct": true, "because": "Unbefugte Nutzung"}, {"text": "Hohe Benutzerfreundlichkeit", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Authentifizierung unwichtig?', 3, '[{"text": "Verifizierungsmethode", "correct": false, "because": "Kern der Authentifizierung"}, {"text": "Sicherheitsstufe", "correct": false, "because": "Entscheidend"}, {"text": "Farbauswahl", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann Authentifizierung mehrstufig sein?', 3, '[{"text": "Ja", "correct": true, "because": "Mehrfaktor möglich"}, {"text": "Nein", "correct": false, "because": "Häufig genutzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Authentifizierung Tokens nutzen kann?', 2, '[{"text": "Ja", "correct": true, "because": "Besitz-basierte Methode"}, {"text": "Nein", "correct": false, "because": "Üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode wähle ich für hohe Sicherheit?', 4, '[{"text": "Zwei-Faktor-Authentifizierung", "correct": true, "because": "Kombiniert Faktoren"}, {"text": "Nur Passwort", "correct": false, "because": "Weniger sicher"}, {"text": "Nur PIN", "correct": false, "because": "Ein Faktor"}]');
